using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using MashBoxSDK.AnimationStudio;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class StudioBevelLargeValidation
{
 public static void Run(){Mesh mesh=null;Mesh cube=null;try{
  var o=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=Object.Instantiate(o.GetComponent<MeshFilter>().sharedMesh);Object.DestroyImmediate(o);var source=new StudioMeshCuts(new StudioModelDocument.Node{mesh=cube});int count=512,n=cube.vertexCount;var positions=new List<Vector3>(count*n);var normals=new List<Vector3>(count*n);var uv=new List<Vector2>(count*n);var triangles=new List<int>();var polygons=new List<int>();var edges=new List<(int,int)>();var cv=cube.vertices;var cn=cube.normals;var cu=cube.uv;var ct=cube.triangles;
  for(int i=0;i<count;i++){var offset=new Vector3((i%16)*1.5f,(i/16)*1.5f,0);for(int j=0;j<n;j++){positions.Add(cv[j]+offset);normals.Add(cn[j]);uv.Add(cu[j]);}foreach(int index in ct)triangles.Add(index+i*n);var seen=new HashSet<(Vector3,Vector3)>();foreach(var face in source.Faces){polygons.Add(0);polygons.Add(face.Vertices.Count);foreach(int index in face.Vertices)polygons.Add(index+i*n);for(int e=0;e<face.Vertices.Count;e++){int a=face.Vertices[e],b=face.Vertices[(e+1)%face.Vertices.Count];if(seen.Add(StudioMeshCuts.NormalEdgePositionKeyForBevel(cv[a],cv[b])))edges.Add((a+i*n,b+i*n));}}}
  mesh=new Mesh();mesh.SetVertices(positions);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();var node=new StudioModelDocument.Node{mesh=mesh,cutPolygons=polygons.ToArray(),cutTriangles=mesh.triangles};var watch=Stopwatch.StartNew();var topology=new StudioMeshCuts(node);var result=topology.BevelEdges(node,edges,new StudioMeshCuts.BevelOptions{Width=.2f,Subdivisions=3,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});watch.Stop();
  if(mesh.vertexCount<=65535||mesh.indexFormat!=IndexFormat.UInt32)throw new Exception("Large bevel did not switch to 32-bit indices");var indices=mesh.triangles;if(indices.Any(i=>i<0||i>=mesh.vertexCount))throw new Exception("Invalid large index buffer");if(result.Edges!=edges.Count)throw new Exception("Missing disconnected selections");if(node.normalGroups.Length!=mesh.vertexCount||mesh.uv.Length!=mesh.vertexCount||mesh.normals.Any(v=>float.IsNaN(v.x)))throw new Exception("Large attribute buffers invalid");
  File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-large-result.txt")),"PASS 32-bit index/large multi-component mesh: "+count+" cubes, "+edges.Count+" selected edges, "+mesh.vertexCount+" output vertices, "+indices.Length/3+" triangles; "+watch.ElapsedMilliseconds+" ms including adjacency and buffer generation.");
 }catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-large-result.txt")),e.ToString());}finally{if(mesh)Object.DestroyImmediate(mesh);if(cube)Object.DestroyImmediate(cube);EditorApplication.Exit(0);}}
}
